insert into public.docs (collection, id, data) values
('settings', 'main', '{"checkIn": "١٢:٠٠ ظهرًا", "checkOut": "٦:٠٠ صباحًا", "deposit": 500, "faq": [{"a": "القسم الأول: مجلس يتسع ٢٥ شخصًا، ومجلس كنب أرضي يتسع ١٦ شخصًا، وجناح بغرفتي نوم.\nالقسم الثاني (الركن اليوناني): مجلس يتسع ٢٥ شخصًا.", "q": "كم سعة كل قسم؟"}, {"a": "نعم، اختر «المزرعة كاملة» وتشمل القسمين، أو احجز كل قسم لحاله.", "q": "هل أقدر أحجز المزرعة كاملة؟"}, {"a": "الدخول الساعة ١٢:٠٠ ظهرًا، والخروج الساعة ٦:٠٠ صباحًا. ويوجد خيار مبيت حتى الساعة ١١:٠٠ ظهرًا.", "q": "متى وقت الدخول والخروج؟"}, {"a": "العربون ٥٠٠ ريال يثبّت الحجز ويُخصم من المبلغ الإجمالي، وهو غير مسترد إذا أُلغي الحجز قبل الموعد بأقل من ٤٨ ساعة.", "q": "كم العربون؟ وهل يُسترد؟"}, {"a": "يُدفع المبلغ المتبقي كاملًا عند وصولك للمزرعة.", "q": "متى أدفع باقي المبلغ؟"}, {"a": "الأسعار الموضحة لأيام الأسبوع، وتختلف في الإجازات الرسمية.", "q": "هل الأسعار ثابتة طوال السنة؟"}, {"a": "في القسم الثاني ملاهي أطفال ونطيطة كبيرة ومراجيح ومنطقة رمل، وفي القسم الأول منطقة طيور (حمام، دجاج، بط) وملاعب ومضمار سياكل.", "q": "وش يناسب الأطفال؟"}, {"a": "عبر واتساب على الرقم 0548409325، أو من زر الواتساب في الصفحة.", "q": "كيف أتواصل معكم؟"}], "mapUrl": "https://maps.app.goo.gl/atK8sTLD1jhYmxFB8", "packages": [{"days": [900, 900, 900, 900, 1200, 1500, 900], "id": "s1day", "in": "١٢:٠٠ ظهرًا", "name": "يوم كامل", "out": "٦:٠٠ صباحًا", "sec": "s1"}, {"days": [700, 700, 700, 700, 900, 1000, 700], "id": "s2day", "in": "١٢:٠٠ ظهرًا", "name": "يوم كامل", "out": "٦:٠٠ صباحًا", "sec": "s2"}, {"days": [1300, 1300, 1300, 1300, 1800, 2500, 1400], "id": "bothday", "in": "١٢:٠٠ ظهرًا", "name": "يوم كامل", "out": "٦:٠٠ صباحًا", "sec": "both"}], "policy": "- العربون ٥٠٠ ريال يثبّت الحجز، ويُخصم من المبلغ الإجمالي.\n- العربون غير مسترد إذا أُلغي الحجز قبل الموعد بأقل من ٤٨ ساعة.\n- المبلغ المتبقي يُدفع كاملًا عند الوصول للمزرعة.", "whatsapp": "966548409325"}'::jsonb),
